    this.eventSource = new EventSource(this.client.buildURL("/api/realtime")),
    this.eventSource.onerror = e => { ... },
    this.eventSource.addEventListener("PB_CONNECT", e => { ... })
}
```

And for subscriptions:
```js
addAllSubscriptionListeners(){
